def max_sum_increasing_subseq(arr, n, k, i):
    # dp[j] stores the maximum sum of an increasing subsequence
    # ending at index j, where the subsequence is strictly increasing
    # and the last element is arr[j].
    dp = [0] * n
    for j in range(n):
        dp[j] = arr[j]
        for m in range(j):
            if arr[m] < arr[j]:
                dp[j] = max(dp[j], dp[m] + arr[j])

    # If k is out of bounds or k <= i, no valid subsequence exists
    if k <= i or k >= n:
        return 0

    # Find the maximum dp value among indices strictly after i
    # and strictly before k.
    best = 0
    for j in range(i + 1, k):
        if dp[j] > best:
            best = dp[j]

    # The subsequence must include arr[k].  The best prefix before k
    # is the best valid prefix ending at some index j with i < j < k.
    # If no such prefix exists, the answer is just arr[k].
    if best == 0 and arr[k] > 0:
        # best remains 0 only when no valid prefix was found;
        # in that case the subsequence consists solely of arr[k].
        pass

    return best + arr[k]
```

