def is_num_keith(n):
    if n < 10:
        return False

    digits = [int(d) for d in str(n)]
    if len(digits) < 3:
        return False

    # Initial sequence: first three digits
    seq = digits[:3]

    # Generate subsequent terms using Fibonacci-like rule
    while True:
        next_val = seq[-1] + seq[-2]
        if next_val != digits[-1]:
            break
        seq.append(next_val)
        if len(seq) == len(digits):
            return True
        # If the next expected digit doesn't match the generated value, stop
        # This handles the case where the sequence diverges
        if len(seq) > len(digits):
            break

    return False
```

